package com.noir.player;

import android.content.*;
import android.content.res.ColorStateList;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.Handler;
import android.view.*;
import android.widget.*;
import java.util.Locale;

/** Edge-to-edge media stage with compact audio controls and an inline video mode. */
public class NativePlayerView extends LinearLayout {
 final MainActivity host;final Handler handler=new Handler();final ImageView artwork;final VideoPane media;
 final TextView title,subtitle,elapsed,total;final SeekBar seek,volume;final SpectrumView spectrum;final Button play,watch,audioMode,previousTrack,nextTrack;final LinearLayout audioControls;boolean dragging,hostActive;int accent;
 final Runnable refresh=new Runnable(){public void run(){if(getVisibility()==VISIBLE&&getWindowVisibility()==VISIBLE)render();handler.postDelayed(this,500);}};
 public NativePlayerView(MainActivity context){super(context);host=context;setOrientation(VERTICAL);setBackgroundColor(Color.BLACK);
  LinearLayout header=new LinearLayout(context);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(12),0,dp(8),0);Button library=button("Library","Open library");library.setOnClickListener(v->host.library());header.addView(library,new LayoutParams(-2,dp(48)));TextView logo=label("Pulse",20,Color.WHITE);logo.setGravity(Gravity.CENTER);logo.setTypeface(null,Typeface.BOLD);header.addView(logo,new LayoutParams(0,-1,1));Button dots=button("Dots","Switch to dot-matrix player");dots.setOnClickListener(v->{host.prefs.edit().putBoolean("dots",true).apply();host.refreshPlayerStyle();});header.addView(dots,new LayoutParams(-2,dp(48)));ImageButton settings=new ImageButton(context);settings.setScaleType(ImageView.ScaleType.FIT_CENTER);settings.setImageDrawable(new PlayerIcons(PlayerIcons.Icon.MORE,Color.WHITE));settings.setPadding(dp(12),dp(12),dp(12),dp(12));settings.setBackgroundColor(Color.TRANSPARENT);settings.setContentDescription("Player settings");settings.setOnClickListener(v->host.settings());header.addView(settings,new LayoutParams(dp(48),dp(48)));addView(header,new LayoutParams(-1,dp(56)));
  LinearLayout modes=new LinearLayout(context);modes.setGravity(Gravity.CENTER);audioMode=button("Audio","Audio mode");watch=button("Video","Video mode");setModeIcon(audioMode,PlayerIcons.Icon.AUDIO);setModeIcon(watch,PlayerIcons.Icon.VIDEO);audioMode.setOnClickListener(v->setVideoMode(false));watch.setOnClickListener(v->setVideoMode(true));modes.addView(audioMode,new LayoutParams(dp(104),dp(48)));LayoutParams mp=new LayoutParams(dp(104),dp(48));mp.leftMargin=dp(6);modes.addView(watch,mp);addView(modes,new LayoutParams(-1,dp(54)));
  media=new VideoPane(context,false);artwork=media.poster;media.onExpand=()->host.openFullscreenVideo(false);media.onRotate=()->host.openFullscreenVideo(true);media.onPoster=()->{if(PlaybackService.current==null)host.library();else if(PlaybackService.current.hasVideo)setVideoMode(true);};media.onModeChanged=this::render;addView(media,new LayoutParams(-1,0,1));
  title=label("Choose your soundtrack",22,Color.WHITE);title.setTypeface(null,Typeface.BOLD);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setGravity(Gravity.CENTER);title.setPadding(dp(20),dp(10),dp(20),0);addView(title,new LayoutParams(-1,-2));subtitle=label("Open your library to start listening",12,0xffaaaaaa);subtitle.setGravity(Gravity.CENTER);subtitle.setMaxLines(1);subtitle.setEllipsize(android.text.TextUtils.TruncateAt.END);subtitle.setPadding(dp(20),dp(5),dp(20),dp(8));subtitle.setOnClickListener(v->{PlaybackService s=PlaybackService.current;if(s!=null&&!s.error.isEmpty())new android.app.AlertDialog.Builder(host).setTitle("Playback error").setMessage(s.error).setPositiveButton("OK",null).show();});addView(subtitle,new LayoutParams(-1,-2));
  audioControls=new LinearLayout(context);audioControls.setOrientation(VERTICAL);audioControls.setPadding(dp(20),0,dp(20),0);addView(audioControls,new LayoutParams(-1,-2));spectrum=new SpectrumView(context);audioControls.addView(spectrum,new LayoutParams(-1,dp(36)));
  seek=new SeekBar(context);seek.setMax(1000);seek.setContentDescription("Playback position");seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){dragging=true;}public void onProgressChanged(SeekBar b,int value,boolean user){PlaybackService s=PlaybackService.current;if(user&&s!=null)elapsed.setText(time((int)(s.duration()*value/1000L)));}public void onStopTrackingTouch(SeekBar b){PlaybackService s=PlaybackService.current;if(s!=null)s.seek((int)(s.duration()*b.getProgress()/1000L));dragging=false;}});audioControls.addView(seek,new LayoutParams(-1,dp(40)));
  LinearLayout times=new LinearLayout(context);elapsed=label("0:00",12,0xffbbbbbb);total=label("0:00",12,0xffbbbbbb);total.setGravity(Gravity.END);times.addView(elapsed,new LayoutParams(0,dp(20),1));times.addView(total,new LayoutParams(0,dp(20),1));audioControls.addView(times);
  LinearLayout transport=new LinearLayout(context);transport.setGravity(Gravity.CENTER);previousTrack=new CashewButton(context,false);previousTrack.setOnClickListener(v->{if(PlaybackService.current!=null)PlaybackService.current.previousTrack();render();});nextTrack=new CashewButton(context,true);nextTrack.setOnClickListener(v->{if(PlaybackService.current!=null)PlaybackService.current.nextTrack();render();});transport.addView(previousTrack,new LayoutParams(dp(56),dp(56)));ImageButton back=transportIcon(PlayerIcons.Icon.BACK_10,"Back 10 seconds");back.setOnClickListener(v->{if(PlaybackService.current!=null)PlaybackService.current.skip(-10000);});transport.addView(back,new LayoutParams(0,dp(56),1));play=button("▶","Play");play.setTextSize(27);play.setOnClickListener(v->{if(PlaybackService.current==null)host.library();else PlaybackService.current.toggle();render();});LayoutParams center=new LayoutParams(dp(64),dp(64));center.setMargins(dp(4),0,dp(4),0);transport.addView(play,center);ImageButton forward=transportIcon(PlayerIcons.Icon.FORWARD_10,"Forward 10 seconds");forward.setOnClickListener(v->{if(PlaybackService.current!=null)PlaybackService.current.skip(10000);});transport.addView(forward,new LayoutParams(0,dp(56),1));transport.addView(nextTrack,new LayoutParams(dp(56),dp(56)));audioControls.addView(transport,new LayoutParams(-1,dp(88)));
  volume=new SeekBar(context);volume.setMax(100);volume.setContentDescription("Media volume");volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int v,boolean user){if(user){android.media.AudioManager a=(android.media.AudioManager)host.getSystemService(Context.AUDIO_SERVICE);a.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,a.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC)*v/100,0);}}});LinearLayout volumeRow=new LinearLayout(context);volumeRow.setGravity(Gravity.CENTER_VERTICAL);volumeRow.addView(label("Volume",12,0xffaaaaaa),new LayoutParams(dp(56),-2));volumeRow.addView(volume,new LayoutParams(0,dp(40),1));audioControls.addView(volumeRow,new LayoutParams(-1,dp(40)));
  LinearLayout bottom=new LinearLayout(context);bottom.setPadding(dp(16),dp(4),dp(16),dp(4));Button files=button("Your library","Open library");files.setOnClickListener(v->host.library());Button online=button("Online","Open online media");online.setOnClickListener(v->host.online());bottom.addView(files,new LayoutParams(0,dp(48),1));bottom.addView(online,new LayoutParams(0,dp(48),1));addView(bottom,new LayoutParams(-1,dp(56)));render();
 }
 int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
 TextView label(String text,int size,int color){TextView view=new TextView(host);view.setText(text);view.setTextSize(size);view.setTextColor(color);return view;}
 Button button(String text,String description){Button b=new Button(host);b.setText(text);b.setContentDescription(description);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(8),0,dp(8),0);b.setBackgroundColor(Color.TRANSPARENT);return b;}
 ImageButton transportIcon(PlayerIcons.Icon icon,String description){ImageButton b=new ImageButton(host);b.setScaleType(ImageView.ScaleType.FIT_CENTER);b.setImageDrawable(new PlayerIcons(icon,Color.WHITE));b.setContentDescription(description);b.setBackgroundColor(Color.TRANSPARENT);b.setPadding(dp(10),dp(14),dp(10),dp(14));return b;}
 void setModeIcon(Button b,PlayerIcons.Icon icon){PlayerIcons drawable=new PlayerIcons(icon,Color.WHITE);drawable.setBounds(0,0,dp(18),dp(18));b.setCompoundDrawables(drawable,null,null,null);b.setCompoundDrawablePadding(dp(6));}
 String time(int ms){return String.format(Locale.US,"%d:%02d",ms/60000,(ms/1000)%60);}
 void setVideoMode(boolean video){PlaybackService s=PlaybackService.current;if(video&&(s==null||!s.hasVideo))return;host.prefs.edit().putBoolean("video_mode",video).apply();render();}
 void setHostActive(boolean value){hostActive=value;media.setHostActive(value);if(value)render();}
 GradientDrawable background(int fill,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 void render(){PlayerPalette palette=PlayerPalette.forIndex(host.prefs.getInt("theme",5));accent=palette.primary;PlaybackService s=PlaybackService.current;boolean video=host.prefs.getBoolean("video_mode",false)&&s!=null&&s.hasVideo;watch.setEnabled(s!=null&&s.hasVideo);watch.setAlpha(watch.isEnabled()?1f:.4f);audioMode.setSelected(!video);watch.setSelected(video);audioMode.setBackground(background(!video?0xff303030:0xff151515,!video?accent:0,14));watch.setBackground(background(video?0xff303030:0xff151515,video?accent:0,14));media.setVideoRequested(video,false);audioControls.setVisibility(video?GONE:VISIBLE);artwork.setPadding(video?0:dp(8),video?0:dp(8),video?0:dp(8),video?0:dp(8));artwork.setBackground(video?background(Color.BLACK,0,0):background(0xff101010,accent,16));
  ColorStateList secondary=ColorStateList.valueOf(palette.secondary),thumb=ColorStateList.valueOf(palette.combo?palette.text:accent);seek.setProgressTintList(secondary);seek.setThumbTintList(thumb);volume.setProgressTintList(secondary);volume.setThumbTintList(thumb);spectrum.color=palette.secondary;spectrum.invalidate();boolean filled=host.prefs.getBoolean("filled",true);GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(filled?accent:Color.BLACK);circle.setStroke(dp(2),accent);play.setBackground(circle);play.setTextColor(filled?palette.filledIcon:accent);previousTrack.setEnabled(s!=null&&s.hasPreviousTrack());nextTrack.setEnabled(s!=null&&s.hasNextTrack());((CashewButton)previousTrack).updateColor(previousTrack.isEnabled()?accent:0xff555555);((CashewButton)nextTrack).updateColor(nextTrack.isEnabled()?accent:0xff555555);
  title.setText(s==null?"Choose your soundtrack":s.title);subtitle.setText(s==null?"Open your library to start listening":!s.error.isEmpty()?"Playback failed • Tap for details":s.loading?"Loading…":!s.artist.isEmpty()?s.artist:video?"VIDEO":"AUDIO");subtitle.setTextColor(s!=null&&!s.error.isEmpty()?accent:0xffaaaaaa);boolean playing=s!=null&&s.playing();play.setText(playing?"Ⅱ":"▶");play.setContentDescription(playing?"Pause":"Play");int duration=s==null?0:s.duration(),position=s==null?0:s.position();if(!dragging){seek.setProgress(duration>0?(int)(1000L*position/duration):0);elapsed.setText(time(position));}total.setText(time(duration));android.media.AudioManager a=(android.media.AudioManager)host.getSystemService(Context.AUDIO_SERVICE);volume.setProgress(100*a.getStreamVolume(android.media.AudioManager.STREAM_MUSIC)/Math.max(1,a.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC)));media.render();
 }
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();handler.post(refresh);}
 @Override protected void onDetachedFromWindow(){handler.removeCallbacks(refresh);media.setHostActive(false);super.onDetachedFromWindow();}
}
